import{_ as e,c as t,o as a,ab as r}from"./chunks/framework.ykMB-S_y.js";const u=JSON.parse('{"title":"python注意","description":"","frontmatter":{"title":"python注意","urlname":"DHU6dmB0zofy7wxx0uGcHxl3nud","date":"2025-04-02 00:26:18","updated":"2025-04-02 00:29:22"},"headers":[],"relativePath":"feishu/docs/编程/语言/DHU6dmB0zofy7wxx0uGcHxl3nud.md","filePath":"feishu/docs/编程/语言/DHU6dmB0zofy7wxx0uGcHxl3nud.md","lastUpdated":1744219990000}'),l={name:"feishu/docs/编程/语言/DHU6dmB0zofy7wxx0uGcHxl3nud.md"},o=r('<h2 id="_1-options处理器" tabindex="-1">1，OPTIONS处理器 <a class="header-anchor" href="#_1-options处理器" aria-label="Permalink to &quot;1，OPTIONS处理器&quot;">​</a></h2><p>OPTIONS处理器是用于处理HTTP OPTIONS请求的组件。在跨域资源共享(CORS)的场景中，OPTIONS请求特别重要。</p><p>当浏览器需要进行跨域请求时，它会先发送一个&quot;预检请求&quot;(preflight request)，使用OPTIONS方法，询问服务器是否允许实际的请求。这个预检请求会包含以下头信息：</p><ol><li><p>Origin - 请求来源</p></li><li><p>Access-Control-Request-Method - 实际请求将使用的HTTP方法</p></li><li><p>Access-Control-Request-Headers - 实际请求将包含的自定义头信息</p></li></ol><p>服务器需要通过OPTIONS处理器响应这些预检请求，返回以下头信息：</p><ol><li><p>Access-Control-Allow-Origin - 允许的来源</p></li><li><p>Access-Control-Allow-Methods - 允许的HTTP方法</p></li><li><p>Access-Control-Allow-Headers - 允许的头信息</p></li><li><p>Access-Control-Max-Age - 预检请求的缓存时间</p></li></ol><p>在您的代码中，Home Assistant已经自动为所有注册的视图添加了OPTIONS处理器，用于处理CORS预检请求。当您尝试再次注册同一URL的OPTIONS处理器时，就会发生冲突，导致错误。</p><p>解决方法是避免重复注册视图，或者在注册视图时检查是否已经存在相同的URL路径。</p><h2 id="_2-跨域请求" tabindex="-1">2，跨域请求 <a class="header-anchor" href="#_2-跨域请求" aria-label="Permalink to &quot;2，跨域请求&quot;">​</a></h2><p>是指浏览器中的JavaScript代码试图访问与当前网页不同&quot;源&quot;(origin)的资源时发生的请求。</p><p>在Web安全模型中，&quot;同源策略&quot;(Same-Origin Policy)是一个重要的安全机制，它限制了一个源的文档或脚本如何与另一个源的资源进行交互。两个URL如果协议、域名和端口都相同，则被认为是同源的。</p><p>例如</p><ul><li><p><a href="https://example.com/page1.html" target="_blank" rel="noreferrer">https://example.com/page1.html</a> 和 <a href="https://example.com/page2.html" target="_blank" rel="noreferrer">https://example.com/page2.html</a> 是同源的</p></li><li><p><a href="https://example.com" target="_blank" rel="noreferrer">https://example.com</a> 和 <a href="https://api.example.com" target="_blank" rel="noreferrer">https://api.example.com</a> 不是同源的(子域名不同)</p></li><li><p><a href="http://example.com" target="_blank" rel="noreferrer">http://example.com</a> 和 <a href="https://example.com" target="_blank" rel="noreferrer">https://example.com</a> 不是同源的(协议不同)</p></li><li><p><a href="https://example.com" target="_blank" rel="noreferrer">https://example.com</a> 和 <a href="https://example.com:8080" target="_blank" rel="noreferrer">https://example.com:8080</a> 不是同源的(端口不同)</p></li></ul><p>当网页需要访问不同源的资源时，就会发生跨域请求。浏览器默认会阻止这些请求，除非目标服务器明确表示允许。</p><p>跨域资源共享(CORS, Cross-Origin Resource Sharing)是一种机制，它使用额外的HTTP头来告诉浏览器允许一个源的网页应用访问不同源的资源。当浏览器发起复杂跨域请求时，会先发送一个&quot;预检&quot;请求(OPTIONS方法)，询问服务器是否允许实际请求。</p><p>在您的天猫精灵集成中，天猫精灵平台可能需要从其域名访问您的Home Assistant服务器，这就构成了跨域请求，需要正确配置CORS头信息才能成功。</p>',16),p=[o];function s(i,n,c,m,h,d){return a(),t("div",null,p)}const x=e(l,[["render",s]]);export{u as __pageData,x as default};
